function showVictory(){document.getElementById("timer").textContent="";const n=(new Date).toLocaleDateString("en-US",{day:"2-digit",month:"long",year:"numeric"});stageContent.innerHTML=`\n\n\n    <div class="certificate">\n\n\n        <div class="certificate-header">\n\n\n            🏆\n\n\n            <h1>\n                CODE BLUE\n            </h1>\n\n\n            <h2>\n                Emergency Response Simulation\n            </h2>\n\n\n            <p>\n                Mansoura Medical Center\n                <br>\n                Emergency Department\n            </p>\n\n\n        </div>\n\n\n\n\n\n        <div class="certificate-body">\n\n\n            <p>\n\n                Mission Completion Certificate\n\n            </p>\n\n\n            <p>\n\n                Awarded to\n\n            </p>\n\n\n\n            <h1 class="name">\n\n                Mariam Hegazy\n\n            </h1>\n\n\n\n            <p>\n\n                For successfully completing the\n\n            </p>\n\n\n\n            <h2>\n\n                Biomedical Emergency Response Simulation\n\n            </h2>\n\n\n\n            <br>\n\n\n\n\n\n            <div class="achievements">\n\n\n                <div>\n                    ✅ Emergency Room Prepared\n                </div>\n\n\n                <div>\n                    ✅ ECG Rhythm Analyzed\n                </div>\n\n\n                <div>\n                    ✅ Defibrillator Restored\n                </div>\n\n\n                <div>\n                    ✅ Patient Stabilized\n                </div>\n\n\n            </div>\n\n\n\n\n            <br>\n\n\n\n\n            <h3>\n\n                Biomedical Engineer\n                <br>\n                Emergency Response Training\n\n            </h3>\n\n\n\n        </div>\n\n\n\n\n\n        <div class="certificate-footer">\n\n\n            <p>\n\n                Mission Status:\n\n                <strong>\n\n                    COMPLETED\n\n                </strong>\n\n            </p>\n\n\n\n            <p>\n\n                ${n}\n\n            </p>\n\n\n        </div>\n\n\n\n\n\n        <button\n            onclick="location.reload()">\n\n            🔄 Replay Mission\n\n        </button>\n\n\n\n    </div>\n\n\n    `,playSound("success")}